import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_sigmoid_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T> struct VecTraits;

template <>
struct VecTraits<float> {
  using T = float;
  static constexpr int VecSize = 4;
  using VecType = float4;
  __device__ static VecType apply(VecType v) {
    v.x = 1.0f / (1.0f + __expf(-v.x));
    v.y = 1.0f / (1.0f + __expf(-v.y));
    v.z = 1.0f / (1.0f + __expf(-v.z));
    v.w = 1.0f / (1.0f + __expf(-v.w));
    return v;
  }
  __device__ static T scalar(T x) {
    return 1.0f / (1.0f + __expf(-x));
  }
};

template <>
struct VecTraits<double> {
  using T = double;
  static constexpr int VecSize = 2;
  using VecType = double2;
  __device__ static VecType apply(VecType v) {
    v.x = 1.0 / (1.0 + exp(-v.x));
    v.y = 1.0 / (1.0 + exp(-v.y));
    return v;
  }
  __device__ static T scalar(T x) {
    return 1.0 / (1.0 + exp(-x));
  }
};

template <typename T>
__global__ void sigmoid_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t N)
{
  using Traits = VecTraits<T>;
  constexpr int VecSize = Traits::VecSize;
  using VecType = typename Traits::VecType;
  // Increase memory-level parallelism per thread by unrolling multiple
  // vectorized chunks per grid-stride iteration. This keeps more
  // independent memory transactions in flight, hiding load/store
  // latency without adding shared memory or changing precision.
  constexpr int Unroll = 4;
  const int64_t vec_stride = (int64_t)blockDim.x * VecSize;
  const int64_t tile_elems = vec_stride * Unroll;
  const int64_t grid_stride = (int64_t)gridDim.x * tile_elems;
  for (int64_t base = (int64_t)blockIdx.x * tile_elems; base < N; base += grid_stride) {
    #pragma unroll
    for (int u = 0; u < Unroll; ++u) {
      const int64_t thread_start = base + (int64_t)u * vec_stride + (int64_t)threadIdx.x * VecSize;
      if (thread_start + VecSize <= N) {
        // Fast vectorized path: direct pointer reinterpretation avoids
        // per-thread CUTE tensor construction overhead and reduces
        // register pressure while keeping fully coalesced 128-bit accesses.
        const VecType* __restrict__ x_v = reinterpret_cast<const VecType*>(X + thread_start);
        VecType* __restrict__ y_v = reinterpret_cast<VecType*>(Y + thread_start);
        // Use read-only data cache path (__ldg) for the vectorized load since X is
        // never written to within this kernel, improving effective memory throughput.
        VecType v = __ldg(x_v);
        v = Traits::apply(v);
        // Streaming store: Y is write-once and never re-read inside this
        // kernel, so bypassing the cache hierarchy on write avoids evicting
        // other useful cache lines and improves effective DRAM bandwidth
        // utilization for this purely memory-bound elementwise kernel.
        __stcs(y_v, v);
      } else if (thread_start < N) {
        // Boundary path, element-wise
        #pragma unroll
        for (int i = 0; i < VecSize; ++i) {
          int64_t idx = thread_start + i;
          if (idx < N) {
            T val = __ldg(&X[idx]);
            __stcs(&Y[idx], Traits::scalar(val));
          }
        }
      }
    }
  }
}

torch::Tensor cute_sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t N = x_c.numel();
  if (N == 0) return y;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  AT_DISPATCH_FLOATING_TYPES(x_c.scalar_type(), "cute_sigmoid_forward", ([&] {
    constexpr int Threads = 512;
    int VecSize = VecTraits<scalar_t>::VecSize;
    int64_t tile_elems = (int64_t)Threads * VecSize;
    int64_t needed_grid = (N + tile_elems - 1) / tile_elems;
    // Cache SM count in a function-local static so we avoid repeated
    // cudaGetDevice/cudaDeviceGetAttribute driver calls on every forward
    // invocation. These synchronous host-side queries were adding fixed
    // per-launch overhead that dominated for this memory-bound kernel.
    static int sm_count = 0;
    if (sm_count == 0) {
      int device = 0;
      cudaGetDevice(&device);
      cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
    }
    // Cap the grid size using a multiplier of the SM count so we launch enough
    // blocks to keep the device saturated via the grid-stride loop, without
    // exceeding it needlessly for small inputs.
    constexpr int BlocksPerSM = 32;
    int64_t max_blocks = (int64_t)sm_count * BlocksPerSM;
    if (max_blocks < 1) max_blocks = 1;
    int64_t grid = (needed_grid < max_blocks) ? needed_grid : max_blocks;
    if (grid < 1) grid = 1;
    dim3 dimBlock(Threads);
    dim3 dimGrid((unsigned int)grid);
    sigmoid_kernel<scalar_t><<<dimGrid, dimBlock, 0, stream>>>(
        x_c.data_ptr<scalar_t>(),
        y.data_ptr<scalar_t>(),
        N
    );
  }));

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "cute_sigmoid_forward launch failed: ", cudaGetErrorString(err));

  return y;
}
